---- orders of 1994
Orders = LOAD ’/home/TPCH/orders.tbl’ USING Pig-Storage(’|’)
AS (o_orderkey:int, ..., o_comment:chararray);
orders_94 = FILTER orders BY o_orderdate MATCHES ’1994.*’;
orders_1994 = FOREACH orders_94 GENERATE o_orderkey,o_custkey;
---- lineitems of 1994
lineitem = LOAD ’/home/TPCH/lineitem.tbl’ USING PigStorage(’|’)
AS (l_orderkey:int, ..., l_comment:chararray);
lineitems_94 = JOIN lineitem BY l_orderkey, orders_1994 BY o_orderkey;
lineitems_1994 = FOREACH lineitems_94 GENERATE
l_orderkey, o_custkey,l_extprice, l_discount,l_suppkey;
---- Region ASIA
region = LOAD ’/home/TPCH/region.tbl’ USING Pig-Storage(’|’)
AS (r_regionkey:int, r_name:chararray, r_comment:chararray);
asia = FILTER region BY r_name MATCHES ’ASIA’;
----- Suppliers of ASIA
supplier = LOAD ’/home/TPCH/supplier.tbl’ USING PigStorage(’|’)
AS (s_suppkey:int, ..., s_comment:chararray);
nation = LOAD ’/home/TPCH/nation.tbl’ USING Pig-Storage(’|’)
AS (n_natkey:int, ..., n_comment:chararray);
join_supp_asia = JOIN asia BY r_regionkey, nation BY n_regionkey;
supp_asia = JOIN join_supp_asia BY n_natkey, supplier BY s_natkey;
supp_nations_asia = FOREACH supp_asia GENERATE s_suppkey,s_natkey,n_name;
----- join all, customers of nations of ASIA
customer = load ’/home/TPCH/customer.tbl’ USING PigStorage(’|’)
AS (c_custkey:int,..., c_comment:chararray);
join_customer_orders = JOIN lineitems_1994 BY o_custkey,
customer BY c_custkey;
join_line_supp = JOIN join_customer_orders BY l_suppkey,
supp_nations_asia BY s_suppkey;
same_nation = FILTER join_line_supp BY s_natkey == c_natkey;
selected = FOREACH same_nation
GENERATE n_name,(l_extprice*(1-l_discount)) AS rev:float;
group_nation = GROUP selected BY n_name;
sum_group = FOREACH group_nation
GENERATE flatten(group), SUM(selected.rev) AS sum_rev;

